package com.example.restaurant.model;import jakarta.persistence.*;import java.time.*;@Entity public class Sale{@Id @GeneratedValue(strategy=GenerationType.IDENTITY) public Long id;@ManyToOne(optional=false) public Restaurant restaurant;public double cashAmount;public double visaAmount;public double spent;public double totalAmount;public LocalDateTime date;@PrePersist @PreUpdate void calc(){totalAmount=cashAmount+visaAmount-spent;if(date==null)date=LocalDateTime.now();}}